#!/usr/bin/env bash
# Launcher of the global R2 run (spec docs/plans/2026-10-10-r2-global-run-spec.md, section 8): size tiers by estimated grid
# size (million cells), ascending inside a tier. Logs in the run folder; the progress lines of the recession are dropped.
# BLAS / OpenMP threads are limited to one per process: with 32 cores every process otherwise reserves about 1 GB for
# thread buffers, which exhausted the commit memory of this PC at the first launch (no effect on the method).
# DO NOT EDIT THIS FILE WHILE A TIER IS RUNNING: bash reads a script while executing it.
# Usage: bash 04_Code/scripts/r2_global_batch.sh small|mid|large1|large2|retry ["parts" [n]]     e.g. small "1 2 3 4 5" 5
cd "$(dirname "$0")/../.." || exit 1
LOG=05_Results/by_date/2026-10-10/r2_global_v1/logs; mkdir -p "$LOG"
export PYTHONIOENCODING=utf-8 OPENBLAS_NUM_THREADS=1 OMP_NUM_THREADS=1 MKL_NUM_THREADS=1
run() { .venv/Scripts/python.exe 04_Code/scripts/r2_global_run_v1.py "$@" 2>&1 | grep --line-buffered -v "^r2 {"; }
tier() { size=$1; name=$2; parts=$3; n=$4; for i in $parts; do run --size "$size" --part "$i/$n" >> "$LOG/${name}_${i}of${n}.log" & done; wait; }
case "$1" in
  small)  tier 0:3 small "${2:-1 2 3 4 5 6}" "${3:-6}" ;;
  mid)    tier 3:10 mid "${2:-1 2}" "${3:-2}" ;;
  large1) tier 10:30 large1 "${2:-1}" "${3:-1}" ;;
  large2) tier 30:100000 large2 "${2:-1}" "${3:-1}" ;;
  retry)  run --size all >> "$LOG/retry.log" ;;
  *) echo "unknown tier $1"; exit 2 ;;
esac
